import com.funk.language.parser.FunkParserImpl; import com.funk.language.typechecker.TypeChecker; import com.funk.language.interpreter.FunkInterpreter; fun main() { val parser = FunkParserImpl(); val typeChecker = TypeChecker(); val interpreter = FunkInterpreter(); try { val program = parser.parse(java.io.File("debug_test.funk").readText()); val typedProgram = typeChecker.typeCheck(program); val (_, context) = interpreter.executeWithContext(typedProgram); println("result1: ${context["result1"]}"); println("result2: ${context["result2"]}"); } catch (e: Exception) { println("Error: ${e.message}"); e.printStackTrace(); } }
